func readAll(r *os.File) ([]byte, error) {
	reader := bufio.NewReader(r)
	data, err := reader.ReadBytes('\n')
	if err != nil && err.Error() != "EOF" {
		return nil, err
	}
	for {
		chunk, err := reader.ReadBytes('\n')
		if len(chunk) == 0 {
			break
		}
		data = append(data, chunk...)
		if err != nil {
			break
		}
	}
	return data, nil
}

type lineIterator struct {
	lines []string
	index int
}

func newLineIterator(lines []string) *lineIterator {
	return &lineIterator{lines: lines, index: 0}
}

func (nl *lineIterator) next() string {
	if nl.index >= len(nl.lines) {
		return ""
	}
	line := strings.TrimSpace(nl.lines[nl.index])
	nl.index++
	return line
}

